-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Fundamentos de UI / UX' and a.numero = 5
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 05 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Atividade Prática — Aula 05', 'PENDENTE', v_aula, 'Atividade — Atividade Prática — Aula 05 (20 questões discursivas)',
      '/MATERIAIS/TECNICO-INFORMATICA-INTERNET/FUNDAMENTOS-DE-UI-UX/ATIVIDADES/ATIVIDADE-PRATICA-AULA-05.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Explique o que é o pilar "Quem" e cite dois aspectos do usuário que devem ser considerados.', 0.2, 'O pilar "Quem" descreve o usuário: perfil, conhecimentos técnicos, limitações visuais ou motoras e familiaridade com sistemas digitais. Dois aspectos válidos: limitação visual ou motora, e familiaridade com o sistema digital (ou conhecimento técnico).', 'Nota cheia: define "Quem" como o usuário e cita dois aspectos do perfil (ex.: limitação visual, motora, familiaridade com sistemas). Metade: define o pilar, mas cita só um aspecto ou aspectos genéricos. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 1, 2, 'Explique o que é o pilar "Onde" e o que ele investiga no ambiente.', 0.4, 'O pilar "Onde" é o ambiente físico da interação. Investiga o espaço físico, o nível de ruído, a iluminação ambiente, a estabilidade e as possíveis distrações ao redor.', 'Nota cheia: define "Onde" como o ambiente físico e cita pelo menos dois fatores investigados (ruído, iluminação, estabilidade, distrações, espaço). Metade: define o ambiente, mas sem citar fatores ou citando um só. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 1, 3, 'Explique por que os pilares "Como" e "Com qual fim" devem ser descritos antes de a tela ser desenhada.', 0.4, 'Os pilares "Como" (dispositivo) e "Com qual fim" (objetivo) precisam ser descritos antes da tela porque definem as restrições da interface (uma ou duas mãos, qualidade da internet, tamanho da tela; meta imediata do usuário) e o que a tela deve permitir. Desenhar antes sem essas informações gera soluções sem base no contexto real.', 'Nota cheia: explica que os dois pilares trazem restrições (dispositivo, rede, bateria, uma ou duas mãos) e a meta do usuário, que orientam o desenho antes da tela. Metade: explica só um dos dois pilares ou fala de forma genérica sobre "conhecer o usuário". Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 2, 1, 'Cite dois fatores físicos do ambiente real que a sala climatizada não reproduz.', 0.2, 'Em ambiente real aparecem a luz solar forte (contraste que cai), o ruído e o barulho do trânsito, a iluminação variável, o uso em movimento (passos, solavancos), gotas de água na tela e a conexão instável. A sala climatizada não reproduz nenhum deles. Basta citar dois.', 'Nota cheia: cita dois fatores físicos reais (luz solar, ruído, movimento, gotas de água, iluminação, conexão). Metade: cita um fator físico ou fator pouco físico (ex.: pressa). Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 2, 2, 'Explique por que o design de software não acontece no vácuo.', 0.4, 'O design de software não acontece no vácuo porque a realidade física impõe desafios visuais, motores e cognitivos imediatos. A tela é usada em um corpo, num lugar e num dispositivo específicos, e não apenas em um monitor.', 'Nota cheia: explica que a realidade física (luz, movimento, ruído, dispositivo) impõe desafios visuais, motores e cognitivos e que o uso depende do contexto. Metade: diz que o contexto importa, sem explicar os desafios. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 2, 3, 'Explique o que muda na análise quando o contexto real de uso é considerado.', 0.4, 'Ao considerar o contexto real, a análise deixa de ser só técnica e passa a medir o efeito no usuário: a tela pode ficar inútil sob sol forte, em ponto de ônibus lotado ou com bateria fraca. Muda a prioridade dos problemas e a forma de testar (testes em situações reais, não só no laboratório).', 'Nota cheia: explica que o contexto real revela falhas que o laboratório não mostra e muda a avaliação e os testes para as condições de uso. Metade: diz que a análise muda, sem explicar como. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 3, 1, 'Explique por que o cenário de uso é uma ferramenta analítica.', 0.2, 'O cenário de uso é uma ferramenta analítica porque descreve a interação com dados concretos (quem usa, onde, com qual dispositivo e para qual objetivo) e serve para tomar decisões de design. Não é narrativa literária.', 'Nota cheia: explica que o cenário é analítico (dados sobre usuário, ambiente, dispositivo e objetivo, usados para decidir o design), e não ficção. Metade: diz que é "analítico" sem explicar por quê. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 3, 2, 'Diga quais variáveis o cenário investiga antes de o primeiro botão ser desenhado.', 0.4, 'O cenário investiga as variáveis que afetam a concentração, a visão e a precisão dos toques do usuário, antes do primeiro botão ser desenhado. As variáveis são as dos quatro pilares: usuário, ambiente, dispositivo e objetivo.', 'Nota cheia: cita variáveis do cenário (ex.: concentração, visão, precisão dos toques, iluminação, ruído, dispositivo, conexão, objetivo) e diz que são analisadas antes do desenho. Metade: cita uma ou duas variáveis, sem ligar ao momento antes do desenho. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 3, 3, 'Explique como a concentração, a visão e a precisão dos toques do usuário são afetadas pelas variáveis do cenário.', 0.4, 'A concentração cai com distrações e pressa (atenção fragmentada, de 2 a 3 segundos entre olhares). A visão piora com luz solar e contraste baixo. A precisão dos toques diminui com passos e solavancos, o que aumenta os toques acidentais em alvos pequenos.', 'Nota cheia: explica o efeito das variáveis sobre as três capacidades (concentração, visão e precisão dos toques), com relação causa e efeito. Metade: explica apenas duas delas ou sem a relação causa e efeito. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 4, 1, 'Explique o que acontece com o contraste aparente da tela em ambientes externos com luz solar.', 0.2, 'Sob luz solar direta, o contraste aparente da tela cai drasticamente, pois o brilho do sol ofusca as cores de baixo contraste e a tela parece mais clara e lavada.', 'Nota cheia: explica que a luz solar reduz o contraste aparente da tela e dificulta a leitura. Metade: diz que o contraste cai, sem explicar o efeito da luz. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 4, 2, 'Explique por que cinza-claro sobre branco pode desaparecer nessa condição.', 0.4, 'Cinza-claro sobre branco tem pouco contraste. Sob sol forte, essa diferença some e o texto desaparece por completo, porque a interface dependia só de tons suaves.', 'Nota cheia: explica que a diferença de tom entre cinza-claro e branco é pequena e some sob a luz solar, deixando o texto invisível. Metade: diz que o cinza-claro tem pouco contraste, sem ligar à luz solar. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 4, 3, 'Descreva uma mitigação de contraste para os textos essenciais e explique como ela ajuda o usuário.', 0.4, 'Mitigação: usar contraste mínimo de 7:1 nos textos essenciais, para que o texto continue legível mesmo com luz solar. Ajuda o usuário porque ele consegue ler as instruções e concluir o agendamento na rua, sem depender do tom suave.', 'Nota cheia: propõe contraste alto e alto nível (ex.: 7:1) para textos essenciais e explica que isso garante a leitura sob sol. Metade: propõe aumentar o contraste, sem valor nem explicação completa. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 5, 1, 'Explique por que fundos puramente brancos causam ofuscamento em locais escuros.', 0.2, 'Em ambiente escuro, o fundo branco puro emite muita luz e contrasta de forma excessiva com o entorno escuro. Isso ofusca a visão e causa cansaço visual rápido.', 'Nota cheia: explica que o fundo branco puro emite muita luz em ambiente escuro, causando ofuscamento e cansaço. Metade: diz que o branco cansa a vista, sem explicar o contraste com o escuro. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 5, 2, 'Explique a função de um botão de tema escuro e claro nessa situação.', 0.4, 'O botão de tema permite alternar entre escuro e claro conforme o ambiente. Em local escuro, o tema escuro reduz o ofuscamento; em local claro, o tema claro mantém a leitura. O usuário ajusta a tela à situação real.', 'Nota cheia: explica que o botão permite trocar o tema conforme a iluminação do ambiente e que isso reduz ofuscamento ou mantém a leitura. Metade: diz que o botão troca o tema, sem ligar à iluminação. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 5, 3, 'Explique por que a solução deve ser pensada junto com o contexto de uso.', 0.4, 'A solução depende do contexto porque o ambiente (escuro ou claro, sol ou sombra) define qual tema e qual contraste servem ao usuário. Sem considerar o local de uso, a correção pode criar outro problema (ex.: tema escuro sob sol forte).', 'Nota cheia: explica que o ambiente determina a solução (tema e contraste) e que ignorar o contexto pode gerar outro problema. Metade: diz que o contexto importa, sem explicar como. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 6, 1, 'Explique o que é atenção fragmentada no contexto de uso.', 0.2, 'Atenção fragmentada é a divisão do olhar do usuário entre o ambiente (obstáculos da rua) e a tela, em intervalos curtos de cerca de 2 a 3 segundos. O usuário não consegue manter a atenção contínua na tela.', 'Nota cheia: explica que a atenção se divide entre a tela e o ambiente em intervalos curtos (2 a 3 segundos). Metade: diz que a atenção é dividida, sem o contexto de uso. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 6, 2, 'Explique por que a tela deve apresentar informações curtas e diretas para esse tipo de uso.', 0.4, 'Com pouca atenção disponível, o usuário precisa entender a tela em um olhar. Informações curtas e diretas cabem nesse intervalo e reduzem o tempo de leitura, enquanto textos longos exigiriam olhares repetidos.', 'Nota cheia: liga informações curtas e diretas ao intervalo de atenção (entendimento rápido, pouco tempo de leitura). Metade: diz que informações curtas ajudam, sem ligar ao intervalo de atenção. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 6, 3, 'Proponha um critério de layout que respeite esse intervalo de atenção.', 0.4, 'Critério de layout: agrupar em uma tela só as informações e a ação principal, com um assunto por etapa e textos curtos, de modo que o usuário conclua cada passo em um ou dois olhares. Também vale destacar a ação principal.', 'Nota cheia: propõe critério concreto de layout (ex.: um assunto por tela ou etapa, textos curtos, ação principal destacada) ligado ao intervalo de 2 a 3 segundos. Metade: propõe um critério genérico ("deixar simples") sem ligar ao intervalo. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 7, 1, 'Explique por que passos e solavancos reduzem a precisão motora.', 0.2, 'Passos e solavancos reduzem a precisão motora porque o corpo se desloca e o dedo não cai no ponto desejado. O toque sai impreciso, sobretudo em áreas pequenas.', 'Nota cheia: explica que o movimento do corpo (passos, solavancos) desestabiliza o dedo e reduz a precisão do toque. Metade: diz que o movimento atrapalha, sem explicar o efeito no toque. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 7, 2, 'Explique o risco que alvos interativos pequenos provocam em situação de movimento.', 0.4, 'Alvos pequenos, em movimento, provocam toques acidentais: o usuário toca o botão vizinho, ou não acerta o alvo e repete o toque, gerando erro e frustração.', 'Nota cheia: explica que alvos pequenos em movimento geram toques errados ou acidentais (acertar o vizinho, errar e repetir). Metade: diz que alvos pequenos causam erro, sem ligar ao movimento. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 7, 3, 'Indique a dimensão mínima de alvo de toque citada na aula e explique o que ela evita.', 0.4, 'A dimensão mínima citada na aula é 48 x 48 pixels para alvos interativos. Ela evita erros frequentes de digitação em situações de movimento, pois dá área suficiente para o dedo acertar o alvo.', 'Nota cheia: indica 48 x 48 pixels (ou 48 px) e explica que evita erros de toque em movimento. Metade: indica o valor sem explicar o que evita, ou explica sem indicar o valor. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 8, 1, 'Explique o que é mitigação no design de interface.', 0.2, 'Mitigação é o ajuste proposital no design para amortecer ou neutralizar uma dificuldade imposta pelo ambiente ou pelo usuário, sem poder eliminar o problema na origem (não se conserta a rua, mas se protege a interação).', 'Nota cheia: define mitigação como ajuste intencional da interface para diminuir ou neutralizar uma dificuldade do contexto. Metade: define de forma vaga ("melhorar a tela"). Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 8, 2, 'Explique por que o espaçamento entre botões vizinhos reduz toques acidentais.', 0.4, 'Espaço entre botões vizinhos cria margem para o dedo acertar o alvo desejado. Sem espaço, o toque em um botão atinge o outro, e o espaçamento reduz esse erro.', 'Nota cheia: explica que o espaço separa os alvos e evita que o toque atinja o botão vizinho. Metade: diz que o espaço ajuda, sem explicar o mecanismo. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 8, 3, 'Cite um valor de espaçamento sugerido na aula e a restrição que ele atende.', 0.4, 'A aula cita 16 px de espaçamento entre botões vizinhos. A restrição atendida é o tremor (ou a imprecisão motora), que faz o dedo sair do alvo quando os botões estão encostados.', 'Nota cheia: indica 16 px (ou 16px) de espaçamento e a restrição (tremor ou precisão motora). Metade: indica o valor sem a restrição, ou a restrição sem o valor. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 9, 1, 'Explique o que é a zona do polegar quando o celular é usado com uma mão.', 0.2, 'A zona do polegar é a área da tela que o polegar alcança com facilidade quando o celular é segurado com uma mão só.', 'Nota cheia: define a zona do polegar como a área da tela alcançada com facilidade pelo polegar ao usar uma mão. Metade: define de forma incompleta (ex.: "a parte de baixo da tela" sem o motivo do alcance). Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 9, 2, 'Diga qual parte da tela o polegar alcança com facilidade nessa situação.', 0.4, 'Com uma mão, o polegar alcança facilmente apenas o terço inferior da tela.', 'Nota cheia: indica o terço inferior (parte de baixo) da tela. Metade: indica a parte de baixo, sem a referência ao terço ou com imprecisão. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 9, 3, 'Explique por que a ação principal deve ficar nessa zona.', 0.4, 'A ação principal, como a confirmação do agendamento, deve ficar na zona do polegar porque é a ação que o usuário mais precisa executar. Assim ele conclui a tarefa sem esticar a mão nem trocar de mão em ônibus ou rua.', 'Nota cheia: explica que a ação principal fica na zona de fácil alcance para o usuário concluir com uma mão, sem esforço. Metade: diz que a ação deve ser fácil de alcançar, sem ligar à ação principal. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 10, 1, 'Explique por que a conexão instável é comum em alguns trechos do trajeto.', 0.2, 'A conexão é instável em trechos como túneis, subsolos, áreas periféricas e aglomerações urbanas, onde a rede móvel sofre quedas repentinas.', 'Nota cheia: cita a característica da rede móvel (quedas em túneis, subsolos, áreas periféricas ou aglomerações) como causa da instabilidade. Metade: diz que a conexão cai, sem citar o local. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 10, 2, 'Explique o risco crítico de perder os dados digitados e a consequência disso para o usuário.', 0.4, 'O risco crítico é perder os dados digitados quando a conexão cai. A consequência para o usuário é frustração extrema e o abandono do serviço, pois ele precisa recomeçar tudo.', 'Nota cheia: identifica a perda de dados digitados como risco crítico e explica a consequência (frustração e abandono do serviço). Metade: cita a perda de dados, sem a consequência. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 10, 3, 'Descreva uma mitigação de interface que proteja os dados e explique como ela funciona.', 0.4, 'Mitigação: salvar automaticamente o rascunho no navegador (armazenamento local, como localStorage) a cada tecla digitada, sem resetar a tela. Quando a conexão cai, os dados já estão guardados e o usuário continua de onde parou.', 'Nota cheia: propõe salvamento local ou automático do rascunho a cada alteração e explica que os dados sobrevivem à queda de conexão. Metade: propõe salvar dados, sem explicar como protegem o usuário. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 11, 1, 'Explique por que o usuário repete o toque nesse caso.', 0.2, 'Sem nenhum sinal de processamento, o usuário acha que o sistema travou ou que o toque não foi registrado, então toca várias vezes por insegurança.', 'Nota cheia: explica que a falta de resposta visual faz o usuário achar que o sistema travou ou não registrou o toque, e por isso repete. Metade: diz que o usuário fica em dúvida, sem explicar a causa. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 11, 2, 'Explique o que a interface deve prever para o estado sem conexão.', 0.4, 'Para o estado sem conexão, a interface deve prever o modo offline: avisar que não há rede, guardar os dados localmente e enviar depois, quando a conexão voltar.', 'Nota cheia: indica que a interface deve avisar a falta de conexão e guardar os dados para envio posterior (modo offline). Metade: diz apenas que deve avisar o usuário sobre a conexão. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 11, 3, 'Explique a relação entre a falta de feedback claro e o abandono do serviço.', 0.4, 'Quando a falta de feedback gera repetição, perda de dados e frustração, o usuário desiste e abandona o serviço. Feedback claro (carregamento, confirmação ou aviso de erro) reduz a ansiedade e mantém o usuário no fluxo.', 'Nota cheia: liga a falta de feedback à frustração e ao abandono, e diz que feedback claro mantém o usuário no fluxo. Metade: liga a falta de feedback à frustração, sem o abandono. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 12, 1, 'Explique o que é sobrecarga cognitiva no uso com pressa.', 0.2, 'Sobrecarga cognitiva é o excesso de informação e de decisões de uma só vez, que a mente não consegue processar com rapidez. Com pressa, o usuário erra ou desiste por não conseguir acompanhar todos os campos.', 'Nota cheia: explica que a sobrecarga é o excesso de informação ou de campos de uma vez, agravado pela pressa, com risco de erro ou desistência. Metade: define sobrecarga sem ligar à pressa. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 12, 2, 'Explique por que dividir um formulário extenso em etapas curtas ajuda o usuário.', 0.4, 'Etapas curtas reduzem a quantidade de campos visíveis ao mesmo tempo, permitindo que o usuário conclua cada parte rapidamente e veja o progresso, sem se sentir sobrecarregado.', 'Nota cheia: explica que dividir em etapas reduz a quantidade de informação por vez e ajuda o usuário a concluir e acompanhar o progresso. Metade: diz que etapas facilitam, sem explicar por quê. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 12, 3, 'Explique como o preenchimento automático de dados já conhecidos reduz a pressa.', 0.4, 'O preenchimento automático de dados já conhecidos (como nome e telefone) elimina a digitação repetida. O usuário gasta menos tempo e menos esforço, e a pressa pesa menos.', 'Nota cheia: explica que dados já conhecidos preenchidos automaticamente diminuem a digitação e o tempo necessário, reduzindo a pressa. Metade: diz que o preenchimento automático ajuda, sem ligar à pressa ou ao esforço. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 13, 1, 'Cite a primeira etapa do quadro e o que ela deve listar.', 0.2, 'A primeira etapa é "Identificar Contexto", que deve listar o usuário, o local e as ferramentas físicas presentes na situação.', 'Nota cheia: indica "Identificar Contexto" e diz que lista usuário, local e ferramentas físicas. Metade: indica a etapa, sem o que deve listar (ou o inverso). Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 13, 2, 'Explique o objetivo da etapa de mapear riscos.', 0.4, 'A etapa "Mapear Riscos" serve para antecipar o que pode dar errado na interação, antes de propor qualquer solução. Assim a equipe sabe quais problemas a solução precisa resolver.', 'Nota cheia: explica que a etapa antecipa as falhas possíveis da interação, para orientar as soluções. Metade: diz que a etapa lista problemas, sem a função de antecipar ou orientar. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 13, 3, 'Explique por que a etapa de checar a viabilidade vem depois de propor as mitigações.', 0.4, 'A viabilidade só pode ser checada depois que as mitigações existem, porque é preciso saber qual solução está sendo avaliada: se ela pode ser feita tecnicamente, no prazo e com o impacto esperado no usuário.', 'Nota cheia: explica que a viabilidade avalia uma mitigação já proposta (técnica, prazo e impacto), por isso vem depois. Metade: diz que a viabilidade vem depois, sem a razão. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 14, 1, 'Diga qual é a primeira etapa da análise de cenário.', 0.2, 'A primeira etapa é descrever o contexto físico, o dispositivo e o perfil do usuário.', 'Nota cheia: indica que a primeira etapa é descrever o contexto físico, o dispositivo e o perfil do usuário. Metade: indica só o contexto ou só o perfil. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 14, 2, 'Explique por que os riscos devem ser mapeados antes de as alternativas serem propostas.', 0.4, 'Os riscos devem ser mapeados antes das alternativas para que as propostas sejam criadas para resolver problemas reais e identificados. Propor antes de mapear leva a soluções sem base e a escolhas por achismo.', 'Nota cheia: explica que mapear riscos primeiro garante que as alternativas resolvam problemas reais do cenário, evitando soluções por achismo. Metade: diz que os riscos vêm antes, sem a razão. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 14, 3, 'Explique o que a matriz de decisão faz com as alternativas de mitigação.', 0.4, 'A matriz de decisão avalia as alternativas de mitigação segundo impacto e viabilidade, e permite escolher a opção com base em fatos. Ela compara as propostas e identifica a melhor delas.', 'Nota cheia: explica que a matriz compara as mitigações por impacto e viabilidade (critérios) e apoia a escolha com base em fatos. Metade: diz que a matriz compara alternativas, sem os critérios. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 15, 1, 'Cite os três critérios primordiais de viabilidade de uma alteração de interface.', 0.2, 'Os três critérios primordiais são viabilidade técnica, tempo de execução e impacto no usuário.', 'Nota cheia: cita os três critérios (viabilidade técnica, tempo de execução e impacto no usuário). Metade: cita dois dos três. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 15, 2, 'Explique o que o critério de viabilidade técnica pergunta.', 0.4, 'O critério de viabilidade técnica pergunta se o sistema atual e o navegador suportam a tecnologia proposta sem travar.', 'Nota cheia: explica que a viabilidade técnica verifica se o sistema e o navegador suportam a tecnologia sem travar. Metade: diz que trata de tecnologia, sem a pergunta sobre o sistema e o navegador. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 15, 3, 'Explique o que o critério de impacto no usuário verifica.', 0.4, 'O critério de impacto no usuário verifica se o esforço de desenvolvimento realmente elimina a dor principal do cenário, isto é, se a mudança resolve o problema que o usuário enfrenta.', 'Nota cheia: explica que o impacto verifica se a mudança elimina a dor principal do usuário no cenário. Metade: diz que trata do usuário, sem a relação com a dor principal. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 16, 1, 'Diga qual proposta deve ser descartada e explique o motivo.', 0.2, 'Deve ser descartada a proposta de reconhecimento de voz, pois tem viabilidade muito baixa na rua (o ruído alto impede a captação), apesar do impacto alto no laboratório.', 'Nota cheia: indica o reconhecimento de voz e cita a viabilidade muito baixa no cenário real (ruído da rua). Metade: indica a proposta sem o motivo, ou o motivo sem indicar a proposta. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 16, 2, 'Explique o que significa escolher com base em fatos.', 0.4, 'Escolher com base em fatos é decidir a partir de dados verificáveis do cenário (impacto, viabilidade, condições físicas e medições), e não por gosto pessoal ou achismo.', 'Nota cheia: explica que a escolha se apoia em dados observáveis e verificáveis do cenário, e não em opinião. Metade: diz que é "com base em dados", sem explicar o que são esses dados. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 16, 3, 'Explique por que uma escolha intuitiva não deve ser aceita sem fatos que a sustentem.', 0.4, 'A escolha intuitiva pode parecer boa, mas se baseia em gosto ou achismo. Sem fatos que a sustentem, a equipe não sabe se a solução resolve o problema real nem se pode ser entregue.', 'Nota cheia: explica que a escolha intuitiva não tem base verificável e pode não resolver o problema real ou não ser viável. Metade: diz que faltam fatos, sem explicar o risco. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 17, 1, 'Explique por que essa opção não deve ser aprovada sem avaliação de viabilidade.', 0.2, 'A proposta não deve ser aprovada sem avaliação de viabilidade porque resolve o problema, mas exige meses de código e tecnologias caras. Ela pode não caber no prazo nem no orçamento da equipe.', 'Nota cheia: explica que a opção exige muito tempo e tecnologia cara, e que precisa ser avaliada quanto à viabilidade (prazo e recursos) antes de aprovar. Metade: diz que é cara ou demorada, sem ligar à avaliação de viabilidade. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 17, 2, 'Descreva a característica de uma decisão que aparece como escolha ótima na matriz.', 0.4, 'Uma decisão que aparece como escolha ótima na matriz é a que mostra alta mitigação comprovada, com viabilidade técnica imediata, ou seja, que resolve o problema e pode ser executada logo.', 'Nota cheia: descreve a escolha ótima como alta mitigação comprovada com viabilidade técnica imediata (resolve o problema e é executável já). Metade: descreve só um dos dois lados (mitigação ou viabilidade). Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 17, 3, 'Explique o que significa viabilidade técnica imediata.', 0.4, 'Viabilidade técnica imediata é a possibilidade de a solução ser feita agora, com a tecnologia que o sistema e o navegador já suportam, sem depender de grandes mudanças ou de recursos que a equipe não tem.', 'Nota cheia: explica que a solução pode ser feita já, com a tecnologia disponível, sem grandes mudanças ou recursos novos. Metade: diz que é "fácil de fazer", sem a relação com a tecnologia disponível. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 18, 1, 'Explique por que colegas que usam aparelhos diferentes podem perceber riscos que você ignorou.', 0.2, 'Colegas que usam aparelhos diferentes ou vivem rotinas distintas percebem riscos que a pessoa que propôs a solução ignorou, porque vivenciam outros contextos de uso (outro celular, outra rotina, outro ambiente).', 'Nota cheia: explica que o colega vive outro contexto ou usa outro aparelho e por isso enxerga riscos diferentes. Metade: diz que o colega vê coisas diferentes, sem a razão do contexto. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 18, 2, 'Explique como testes de cenários e evidências ergonômicas resolvem a discordância.', 0.4, 'A discordância se resolve com testes de cenários e evidências ergonômicas, isto é, com dados observados em situações reais de uso e não com a opinião de cada um.', 'Nota cheia: indica testes de cenários e evidências ergonômicas como forma de resolver a divergência com fatos. Metade: diz que se resolve com "testes" ou "dados", sem o tipo de evidência. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 18, 3, 'Explique por que vale considerar a ideia do colega antes de defender a sua escolha.', 0.4, 'Vale considerar a ideia do colega antes de defender a sua escolha porque ele pode estar enxergando um risco real. Ouvir a proposta permite comparar as opções com fatos e chegar à solução mais fundamentada para o usuário.', 'Nota cheia: explica que ouvir a ideia pode revelar riscos reais e permite comparar as opções com fatos antes de decidir. Metade: diz que é preciso ouvir o colega, sem explicar o ganho. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 19, 1, 'Explique o princípio de amabilidade citado na aula.', 0.2, 'O princípio de amabilidade (S4) diz que discordâncias sobre telas devem ser resolvidas com testes de cenários e evidências ergonômicas, nunca com ataques pessoais.', 'Nota cheia: explica que a discordância deve ser tratada com evidências e testes, nunca com ataques pessoais. Metade: diz que é "ser educado" ou "não atacar", sem as evidências. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 19, 2, 'Diga com que tipo de argumento as discordâncias sobre telas devem ser resolvidas.', 0.4, 'As discordâncias sobre telas devem ser resolvidas com argumentos sobre o uso, como testes de cenários e evidências ergonômicas, e não com opiniões pessoais sobre a pessoa.', 'Nota cheia: indica argumentos sobre o uso (testes de cenários e evidências ergonômicas). Metade: indica "argumentos" ou "fatos" sem o tipo. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 19, 3, 'Explique como manter a conversa centrada na tela e não na pessoa.', 0.4, 'A conversa fica centrada na tela quando se descreve o problema da interface (o que acontece, em qual situação, com qual dado), e não o comportamento ou a pessoa do colega. Por exemplo: "o botão fica fora do alcance do polegar", em vez de "você não sabe fazer design".', 'Nota cheia: explica que a conversa foca no problema da tela (o que, onde, quando) e não na pessoa, com exemplo ou descrição clara. Metade: diz que é preciso focar na tela, sem explicar como. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 20, 1, 'Explique como o contexto dita o tamanho dos elementos e o nível de contraste exigido.', 0.2, 'O contexto dita o tamanho dos elementos e o nível de contraste: na rua, sob sol forte, os textos precisam de contraste alto (7:1 nos essenciais) e os elementos precisam ser maiores para serem lidos e tocados.', 'Nota cheia: liga o contexto de rua e sol ao tamanho dos elementos e ao contraste alto (ex.: 7:1 para textos essenciais). Metade: diz que o contexto exige contraste ou tamanho maior, sem o vínculo claro. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 20, 2, 'Explique como as restrições físicas definem a hierarquia e o posicionamento das ações principais.', 0.4, 'As restrições físicas (uso com uma mão, passos, pressa) definem que a ação principal deve ficar na zona do polegar, na parte inferior da tela, e que a hierarquia deve destacar essa ação, com botões de 48 px ou mais e espaçamento entre eles.', 'Nota cheia: liga as restrições físicas (uma mão, movimento) à hierarquia e à posição da ação principal na zona do polegar. Metade: fala em posição ou hierarquia, sem ligar às restrições físicas. Zero: em branco, errado, fora do tema ou copiado.'),
      (v_atividade, 20, 3, 'Proponha uma mitigação técnica viável para esse cenário e justifique a viabilidade dela.', 0.4, 'Mitigação técnica viável: salvar automaticamente os dados no navegador (localStorage), dividir o formulário em etapas curtas e usar botões e textos maiores. É viável porque usa HTML, CSS e armazenamento local simples, sem tecnologia cara, e resolve a perda de dados e os erros de toque.', 'Nota cheia: propõe uma mitigação concreta (ex.: salvamento local, etapas curtas, alvos maiores) e justifica a viabilidade (tecnologia simples, prazo, impacto no usuário). Metade: propõe a mitigação, sem justificar a viabilidade. Zero: em branco, errado, fora do tema ou copiado.');
end $$;
